css:
.fx-opn{width:min(420px,100%)}
.fx-opn .tools{display:flex;gap:.6em;align-items:center;margin-bottom:1em;font-size:.82em;opacity:.8}
.fx-opn select{font:600 1em var(--font-body);padding:.35em .6em;border:1px solid var(--border);border-radius:calc(var(--radius)*.5);background:var(--surface);color:var(--text)}
.fx-opn .card{border:1px solid var(--border);border-radius:var(--radius);background:var(--surface);overflow:hidden}
.fx-opn .top{display:flex;gap:.8em;align-items:center;padding:1em 1.1em;width:100%;border:0;background:none;color:var(--text);cursor:pointer;text-align:left;font:inherit}
.fx-opn .dot{width:.8em;height:.8em;border-radius:50%;background:var(--c);box-shadow:0 0 0 0 color-mix(in srgb,var(--c) 55%,transparent);flex:none}
.fx-opn [data-s=open]{--c:var(--accent)}.fx-opn [data-s=soon]{--c:var(--secondary)}.fx-opn [data-s=closed]{--c:color-mix(in srgb,var(--text) 45%,var(--surface))}
.fx-opn [data-s=open] .dot{animation:fx-opn-p 2s infinite}
@keyframes fx-opn-p{70%{box-shadow:0 0 0 .6em transparent}}
.fx-opn .top b{display:block}.fx-opn .top small{opacity:.7}
.fx-opn .top .chev{margin-left:auto;transition:transform calc(.25s/var(--speed))}
.fx-opn .top[aria-expanded=true] .chev{transform:rotate(180deg)}
.fx-opn .tbl{display:grid;grid-template-rows:0fr;transition:grid-template-rows calc(.3s/var(--speed))}
.fx-opn .tbl.on{grid-template-rows:1fr}
.fx-opn .tbl>div{overflow:hidden}
.fx-opn ul{list-style:none;margin:0;padding:.2em 1.1em 1em;display:grid;gap:.15em;font-size:.92em}
.fx-opn li{display:flex;justify-content:space-between;padding:.4em .6em;border-radius:.5em}
.fx-opn li.today{background:color-mix(in srgb,var(--accent) 16%,var(--surface));font-weight:700}
@media(prefers-reduced-motion:reduce){.fx-opn [data-s=open] .dot{animation:none}.fx-opn .tbl,.fx-opn .top .chev{transition:none}}

