(function(){
/* ── edit these ─────────────────────────────── */
var TZ='Asia/Kuala_Lumpur';
var HOURS=[[11,20],[10,22],[10,22],[10,22],[10,22],[10,23],[10,23]]; /* Sun..Sat as [open,close] hours; null = closed */
var HOLIDAYS=['2026-10-20','2026-12-25']; /* yyyy-mm-dd */
/* ───────────────────────────────────────────── */
var D=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
var r=document.querySelector('.fx-opn'),c=r.querySelector('#fx-opn-c'),a=r.querySelector('#fx-opn-a'),bb=r.querySelector('#fx-opn-b'),l=r.querySelector('#fx-opn-l'),t=r.querySelector('#fx-opn-t'),tb=r.querySelector('.top'),sim=r.querySelector('#fx-opn-sim');
function fmt(h){var m=Math.round((h%1)*60),H=Math.floor(h),s=H>=12?'pm':'am',x=H%12||12;return x+(m?':'+('0'+m).slice(-2):'')+s}
function now(){var v=sim.value;if(v){var p=v.split(',');return{d:+p[0],t:+p[1]+(+p[2])/60,date:p[3]||''}}
 try{var f=new Intl.DateTimeFormat('en-GB',{timeZone:TZ,weekday:'short',hour:'numeric',minute:'numeric',hour12:false,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),o={};f.forEach(function(x){o[x.type]=x.value});
 return{d:['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(o.weekday),t:(+o.hour%24)+(+o.minute)/60,date:o.year+'-'+o.month+'-'+o.day}}catch(e){var n=new Date();return{d:n.getDay(),t:n.getHours()+n.getMinutes()/60,date:''}}}
function nextOpen(n){for(var i=0;i<8;i++){var d=(n.d+i)%7,h=HOURS[d];if(!h)continue;if(i===0&&n.t>=h[0])continue;return{day:i===0?'today':i===1?'tomorrow':D[d],h:h[0]}}return null}
function draw(){var n=now(),h=HOURS[n.d],hol=HOLIDAYS.indexOf(n.date)>-1,s,A,B;
 if(!hol&&h&&n.t>=h[0]&&n.t<h[1]){var left=h[1]-n.t;if(left<=1){s='soon';A='Closing soon';B='Closes at '+fmt(h[1])}else{s='open';A='Open now';B='Until '+fmt(h[1])+' today'}}
 else{s='closed';A=hol?'Closed for the holiday':'Closed now';var o=nextOpen(n);B=o?'Opens '+o.day+' at '+fmt(o.h):'See hours'}
 c.dataset.s=s;a.textContent=A;bb.textContent=B;
 l.innerHTML=D.map(function(x,i){return '<li'+(i===n.d?' class="today"':'')+'><span>'+x+'</span><span>'+(HOURS[i]?fmt(HOURS[i][0])+' – '+fmt(HOURS[i][1]):'Closed')+'</span></li>'}).join('')}
tb.onclick=function(){var o=tb.getAttribute('aria-expanded')!=='true';tb.setAttribute('aria-expanded',o);t.classList.toggle('on',o)};
sim.onchange=draw;draw();setInterval(draw,60000)})();
